window.AUTH=window.AUTH||{};window.AUTH["24-1068"]={"d":"24-1068","id":"2025/24-1068","n":"Monsanto Company v. Durnell","briefs":[{"k":"petitioner","label":"Brief of petitioner Monsanto Company","date":"2026-02-23","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/397048/20260223143047764_24-1068%20Final%20Monsanto%20Co.%20v%20Durnell%20merits%20opening%20brief.pdf","side":"pet","n":81},{"k":"united-states","label":"Brief amicus curiae of the United States","date":"2026-03-02","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/399785/20260302183259184_24-1068%20Monsanto%20tsac.pdf","side":"us","n":74},{"k":"respondent","label":"Brief of respondent John L. Durnell","date":"2026-03-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/401848/20260325162306480_24-1068%20Brief.pdf","side":"res","n":68},{"k":"united-states","label":"Brief amicus curiae of United States Senator Cory Booker","date":"2026-04-01","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/403423/20260401135526093_Amicus%20Brief%20of%20Senator%20Booker%20Final.pdf","side":"us","n":18},{"k":"reply","label":"Reply of petitioner Monsanto Company","date":"2026-04-17","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/404756/20260417143840724_1.%202026-04-17%20Monsanto%20v.%20Durnell%20Reply%20Final.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r61_3314.pdf","tr":true,"items":[{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"by":{"0":"27"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"by":{"0":"2, 4, 5, 6, 26, 29, 32, 33, 34, 35, 40","1":"3-5, 7, 12, 15-21, 23, 25, 27, 28, 33","2":"2, 3, 4, 10, 10–11, 12, 16, 18, 31, 33, 34, 44, 45, 46, 48, 49, 50","3":"2, 11, 18","4":"2, 6, 7, 15"},"q":[{"src":"brief","b":0,"text":"reflect[s] [a] determination on the part of EPA","cite":"544 U.S. at 440"},{"src":"brief","b":0,"text":"set a standard for a product’s labeling,","cite":"544 U.S. at 443, 446"},{"src":"brief","b":1,"text":"pre-empts any statutory or commonlaw rule that would impose a labeling requirement that diverges from those set out in FIFRA and its implementing regulations.","cite":"544 U.S. 431, 452"},{"src":"brief","b":1,"text":"‘transform[] FIFRA from a labeling law into a comprehensive regulatory statute.’","cite":"544 U.S. at 437"},{"src":"brief","b":2,"text":"States may ban or restrict the uses of pesticides that EPA has approved.","cite":"544 U.S. at 450"},{"src":"brief","b":2,"text":"on the relevant FIFRA misbranding standards.","cite":"544 U.S. at 454"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"A requirement is a rule of law that must be obeyed.","cite":"544 U. S., at 445"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"FIFRA contemplates that pesticide labels will evolve over time.","cite":"544 U. S., at 451"},{"src":"argument","who":"Mr. Clement","text":"Bates held as much. Nonetheless, he insists that unless Congress expressly directs the agency to bind the judiciary, then the requirements that are imposed on a particular pesticide in the registration process and backed by criminal penalties are not federal requirements."},{"src":"argument","who":"Mr. Clement","text":"Efficacy, as I think you know, is different, and that's why I think the Bates case is quite distinguishable because the agency actually doesn't have to evaluate efficacy."},{"src":"argument","who":"Justice Jackson","text":"So I -- my understanding is that under Bates and the way the statute reads in saying that registration is not a defense to -- to the offense of misbranding, that you could have a product that is registered that becomes misbranded."}]},{"t":"case","label":"CTIA v. City of Berkeley","cite":"928 F.3d 832","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/928/832/","by":{"0":"52"},"q":[{"src":"brief","b":0,"text":"diminish the believability and credibility of warnings in general, [as] such warnings are tantamount to ‘crying wolf.’","cite":"928 F.3d 832, 854-55"}]},{"t":"case","label":"Freightliner Corp. v. Myrick","cite":"514 U.S. 280","y":1995,"id":"1994/94-286","sc":1,"by":{"0":"46"}},{"t":"case","label":"Mason v. SmithKline Beecham Corp.","cite":"596 F.3d 387","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/387/","by":{"0":"42"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"by":{"0":"30, 32, 34","1":"15, 20","4":"5"},"q":[{"src":"brief","b":0,"text":"the Federal Government has weighed the competing interests relevant to the particular requirement in question, reached an unambiguous conclusion about how those competing considerations should be resolved in a particular case or set of cases, and implemented that conclusion via a specific mandate on manufacturers.","cite":"518 U.S. at 501"},{"src":"brief","b":1,"text":"weigh[s] the competing interests relevant to the particular requirement in question, reache[s] an unambiguous conclusion about how those competing considerations should be resolved in a particular case or set of cases, and implement[s] that conclusion via a specific mandate on manufacturers.","cite":"518 U.S. at 501"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"provide a traditional damages remedy for violations of common-law duties when those duties Jackson, J., dissenting parallel federal requirements.","cite":"518 U. S. 470, 495"}]},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"587 U.S. 299","y":2019,"id":"2018/17-290","sc":1,"by":{"0":"47, 48","1":"20, 29, 30, 32, 34","2":"3, 36, 42, 43","4":"23"},"q":[{"src":"brief","b":0,"text":"even after the manufacturer has made them,","cite":"587 U.S. at 315"},{"src":"brief","b":0,"text":"informed the [pesticide] manufacturer that the [EPA] would not approve changing the [pesticide’s] label to include that warning.","cite":"587 U.S. at 314"},{"src":"brief","b":1,"text":"actual conflict between state and federal law","cite":"587 U.S. at 315"},{"src":"brief","b":2,"text":"show that it fully informed the [agency] of the justifications for the warning required by state law and that the [agency], in turn, informed the … manufacturer that the [agency] would not approve changing the [product’s] label to include that warning.","cite":"587 U.S. at 314"}]},{"t":"case","label":"Moore v. Ford Motor Co.","cite":"332 S.W.3d 749","y":2011,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.3d/332/749/","by":{"0":"40, 41","1":"16, 24","2":"3, 12, 13"},"q":[{"src":"brief","b":0,"text":"did not give adequate warning of the danger.","cite":"332 S.W.3d 749, 756"},{"src":"brief","b":0,"text":"concept of unreasonable danger … is presented to the jury as an ultimate issue without further definition.","cite":"332 S.W.3d at 756"},{"src":"brief","b":1,"text":"did not give adequate warning of the danger.","cite":"332 S.W.3d 749, 756"}]},{"t":"case","label":"Mut. Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"by":{"0":"43, 45, 46","1":"29, 30, 34","2":"19, 37, 44","4":"22"},"q":[{"src":"brief","b":0,"text":"to comply with both state and federal requirements.","cite":"570 U.S. 472, 480"},{"src":"brief","b":0,"text":"altering its labeling are in conflict with federal laws that prohibit manufacturers from unilaterally altering … labeling.","cite":"570 U.S. at 490"},{"src":"brief","b":1,"text":"[w]hen federal law forbids an action that state law requires, the state law is ‘without effect.’","cite":"570 U.S. 472, 486"},{"src":"brief","b":1,"text":"forbid[] the use of that label.","cite":"570 U.S. at 490"},{"src":"brief","b":4,"text":"not … sell the drug[s] without adequate warnings.","cite":"570 U.S. at 489 n.5"}]},{"t":"case","label":"Nat’l Ass’n of Wheat Growers v. Bonta","cite":"85 F.4th 1263","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/85/1263/","by":{"0":"12, 13, 15, 16, 17, 18, 52","4":"8"},"q":[{"src":"brief","b":0,"text":"distinction between hazard and risk is significant.","cite":"85 F.4th at 1269"},{"src":"brief","b":0,"text":"significant number of international regulatory authorities and organizations disagree with IARC’s conclusion that glyphosate is a probable carcinogen.","cite":"85 F.4th at 1270"}]},{"t":"case","label":"NRDC v. EPA","cite":"38 F.4th 34","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/34/","by":{"0":"17, 31, 49","1":"10, 28","2":"15"},"q":[{"src":"brief","b":2,"text":"glyphosate is not likely to be carcinogenic to humans.","cite":"38 F.4th 34, 43"}]},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"by":{"0":"21, 44, 45, 46, 47, 48","1":"3, 13, 29, 30-33","2":"36","4":"17, 22"},"q":[{"src":"brief","b":0,"text":"[t]he question … is whether the private party could independently do under federal law what state law requires of it.","cite":"564 U.S. 604, 620"},{"src":"brief","b":0,"text":"authority to eventually rescind Wyeth’s unilateral CBE changes,","cite":"564 U.S. at 624 n.8"},{"src":"brief","b":1,"text":"independently chang[ing] their labels to satisfy their state-law duty.","cite":"564 U.S. 604, 618"},{"src":"brief","b":4,"text":"independently do under federal law what state law requires of it.","cite":"564 U.S. 604, 620"},{"src":"brief","b":4,"text":"Indeed, if the option of ceasing to act defeated a claim of impossibility, impossibility preemption would be ‘all but meaningless.’","cite":"564 U.S. at 621"},{"src":"argument","who":"Justice Sotomayor","text":"PLIVA and Wyeth are also there. Doesn't the history we're showed about the manufacturer who added the California 50 proposition information without FDA -- FDA approval, doesn't that defeat your impossibility argument?"},{"src":"argument","who":"Mr. Clement","text":"So I don't think -- my answer to that would be I don't think PLIVA and Bartlett come out differently if you could point to a couple of generic manufacturers who, ultra vires and in a way that they actually weren't allowed to, tried to change the label on the -- their generic pharmaceutical."},{"src":"argument","who":"Mr. Clement","text":"I think you can sort of think about this like Riegel was an express preemption case and just an express preemption case. But, of course, when Justice Scalia decided Riegel, he didn't have the benefit of PLIVA and Bartlett, which come later."}]},{"t":"case","label":"Reckitt Benckiser, Inc. v. Jackson","cite":"762 F. Supp. 2d 34","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/762/34/","by":{"0":"39","1":"26"},"q":[{"src":"brief","b":0,"text":"stands for the unremarkable proposition that a registration is not a defense against an allegation that a product violates the terms of that registration.","cite":"762 F.Supp.2d 34, 45"},{"src":"brief","b":1,"text":"stands for the unremarkable proposition that a registration is not a defense against an allegation that a product violates the terms of that registration.","cite":"762 F. Supp. 2d 34, 45"}]},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"by":{"0":"28, 29, 37, 39, 43","1":"12, 21, 22, 34","2":"49, 50","4":"4, 5, 13, 14"},"q":[{"src":"brief","b":0,"text":"s[aw] only the cost of a more dangerous design.","cite":"552 U.S. at 325"},{"src":"argument","who":"Mr. Clement","text":"That defies common sense, the statutory text, and this Court's precedents, in particular, this Court's 8-to-1 decision in Riegel, where this Court held that similar agency-imposed requirements on a particular device are federal requirements for preemption purposes."},{"src":"argument","who":"Mr. Clement","text":"But the language of FIFRA's preemption provision, just like the language of the preemption provision for the medical device amendments that were at issue in the Riegel case, both of those uses the word \"under,\" and I think that word textually captures the various requirements that are imposed at a device-specific level or a herbicide-specific level in the context of the registration process here."},{"src":"argument","who":"Mr. Clement","text":"And I don't think the situation's any different for purposes of medical device amendments in this Court's decision in Riegel. You could have the same situation where there's additional information that comes to light, and there are processes for getting all of that in front of the agency."}]},{"t":"case","label":"Rodriguez v. Suzuki Motor Co.","cite":"996 S.W.2d 47","y":1999,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/996/47/","by":{"0":"41","2":"13"},"q":[{"src":"brief","b":0,"text":"give the concept of unreasonable danger content ‘by applying their collective intelligence and experience to the broad evidentiary spectrum of facts and circumstances presented by the parties.’","cite":"996 S.W.2d 47, 65"},{"src":"brief","b":2,"text":"to argue that the utility of a design outweighs its risks.","cite":"996 S.W.2d 47, 65"}]},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"by":{"0":"5, 7","1":"4, 26"},"q":[{"src":"brief","b":0,"text":"the use, as well as the sale and labeling, of pesticides.","cite":"467 U.S. at 991"},{"src":"brief","b":1,"text":"FIFRA was primarily a licensing and labeling statute.","cite":"467 U.S. 986, 991"},{"src":"brief","b":1,"text":"transformed FIFRA * * * into a comprehensive regulatory statute.","cite":"467 U.S. 986, 991"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"[W]here Congress includes particular language in one section of a statute but omits it in another section of the same Act, it is generally presumed that Congress acts intentionally and purposely in the disparate inclusion or exclusion.","cite":"464 U.S. 16, 23"}]},{"t":"case","label":"Schaffner v. Monsanto Corp.","cite":"113 F.4th 364","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/113/364/","by":{"0":"10, 30, 31, 37","1":"22, 26, 31, 33","4":"20"},"q":[{"src":"brief","b":0,"text":"employ[ed] glyphosate as its active ingredient.","cite":"113 F.4th 364, 373"},{"src":"brief","b":0,"text":"contents required to be included on a pesticide label.","cite":"113 F.4th at 390"}]},{"t":"case","label":"Stearns Elec. Paste Co. v. EPA","cite":"461 F.2d 293","y":1972,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/461/293/","by":{"0":"4, 5"},"q":[{"src":"brief","b":0,"text":"absolute right to have [a] product registered under protest.","cite":"461 F.2d at 303"}]},{"t":"case","label":"Stengel v. Medtronic Inc.","cite":"704 F.3d 1224","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/1224/","by":{"0":"39"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"by":{"0":"44, 47","1":"29, 30, 34","2":"39"},"q":[{"src":"brief","b":1,"text":"ill equipped to perform the [agency’s] cost-benefit-balancing function.","cite":"555 U.S. at 626"},{"src":"argument","who":"Justice Sotomayor","text":"PLIVA and Wyeth are also there. Doesn't the history we're showed about the manufacturer who added the California 50 proposition information without FDA -- FDA approval, doesn't that defeat your impossibility argument?"},{"src":"argument","who":"Justice Jackson","text":"What about Wyeth? Is this like Wyeth?"},{"src":"argument","who":"Ms. Harris","text":"I -- no, it's completely different from Wyeth. There's a very stark contrast. For the changes to be affected regulations for the FDA for brand manufacturers in Wyeth, it really was you, brand manufacturer, out loud, unilaterally, to change your label for this period of time, FDA will then tell you if it disagrees."}]},{"t":"usc","label":"7 U.S.C. § 136","url":"https://www.law.cornell.edu/uscode/text/7/136","subs":["(q)(1)","(q)(1)(E)","(q)(2)","(t)","(x)","(bb)","(q)(1)(A)","(q)(1)(B)","(q)(1)(G)","(q)","(u)"],"stext":{"head":"§136. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Active ingredient"],[0,"The term \"active ingredient\" means—"],[1,"(1) in the case of a pesticide other than a plant regulator, defoliant, desiccant, or nitrogen stabilizer, an ingredient which will prevent, destroy, repel, or mitigate any pest;"],[1,"(2) in the case of a plant regulator, an ingredient which, through physiological action, will accelerate or retard the rate of growth or rate of maturation or otherwise alter the behavior of ornamental or crop plants or the product thereof;"],[1,"(3) in the case of a defoliant, an ingredient which will cause the leaves or foliage to drop from a plant;"],[1,"(4) in the case of a desiccant, an ingredient which will artificially accelerate the drying of plant tissue; and"],[1,"(5) in the case of a nitrogen stabilizer, an ingredient which will prevent or hinder the process of nitrification, denitrification, ammonia volatilization, or urease production through action affecting soil bacteria."],[0,"(b) Administrator"],[0,"The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[0,"(c) Adulterated"],[0,"The term \"adulterated\" applies to any pesticide if—"],[1,"(1) its strength or purity falls below the professed standard of quality as expressed on its labeling under which it is sold;"],[1,"(2) any substance has been substituted wholly or in part for the pesticide; or"],[1,"(3) any valuable constituent of the pesticide has been wholly or in part abstracted."],[0,"(d) Animal"],[0,"The term \"animal\" means all vertebrate and invertebrate species, including but not limited to man and other mammals, birds, fish, and shellfish."],[0,"(e) Certified applicator, etc."],[0,"(1) Certified applicator"],[1,"The term \"certified applicator\" means any individual who is certified under section 136i of this title as authorized to use or supervise the use of any pesticide which is classified for restricted use. Any applicator who holds or applies registered pesticides, or uses dilutions of registered pesticides consistent with subsection (ee), only to provide a service of controlling pests without delivering any unapplied pesticide to any person so served is not deemed to be a seller or distributor of pesticides under this subchapter."],[0,"(2) Private applicator"],[1,"The term \"private applicator\" means a certified applicator who uses or supervises the use of any pesticide which is classified for restricted use for purposes of producing any agricultural commodity on property owned or rented by the applicator or the applicator's employer or (if applied without compensation other than trading of personal services between producers of agricultural commodities) on the property of another person."],[0,"(3) Commercial applicator"],[1,"The term \"commercial applicator\" means an applicator (whether or not the applicator is a private applicator with respect to some uses) who uses or supervises the use of any pesticide which is classified for restricted use for any purpose or on any property other than as provided by paragraph (2)."],[0,"(4) Under the direct supervision of a certified applicator"],[1,"Unless otherwise prescribed by its labeling, a pesticide shall be considered to be applied under the direct supervision of a certified applicator if it is applied by a competent person acting under the instructions and control of a certified applicator who is available if and when needed, even though such certified applicator is not physically present at the time and place the pesticide is applied."],[0,"(f) Defoliant"],[0,"The term \"defoliant\" means any substance or mixture of substances intended for causing the leaves or foliage to drop from a plant, with or without causing abscission."],[0,"(g) Desiccant"],[0,"The term \"desiccant\" means any substance or mixture of substances intended for artificially accelerating the drying of plant tissue."],[0,"(h) Device"],[0,"The term \"device\" means any instrument or contrivance (other than a firearm) which is intended for trapping, destroying, repelling, or mitigating any pest or any other form of plant or animal life (other than man and other than bacteria, virus, or other microorganism on or in living man or other living animals); but not including equipment used for the application of pesticides when sold separately therefrom."],[0,"(i) District court"],[0,"The term \"district court\" means a United States district court, the District Court of Guam, the District Court of the Virgin Islands, and the highest court of American Samoa."],[0,"(j) Environment"],[0,"The term \"environment\" includes water, air, land, and all plants and man and other animals living therein, and the interrelationships which exist among these."],[0,"(k) Fungus"],[0,"The term \"fungus\" means any non-chlorophyll-bearing thallophyte (that is, any non-chlorophyll-bearing plant of a lower order than mosses and liverworts), as for example, rust, smut, mildew, mold, yeast, and bacteria, except those on or in living man or other animals and those on or in processed food, beverages, or pharmaceuticals."],[0,"(l) Imminent hazard"],[0,"The term \"imminent hazard\" means a situation which exists when the continued use of a pesticide during the time required for cancellation proceeding would be likely to result in unreasonable adverse effects on the environment or will involve unreasonable hazard to the survival of a species declared endangered or threatened by the Secretary pursuant to the Endangered Species Act of 1973 [16 U.S.C. 1531 et seq.]."],[0,"(m) Inert ingredient"],[0,"The term \"inert ingredient\" means an ingredient which is not active."],[0,"(n) Ingredient statement"],[0,"The term \"ingredient statement\" means a statement which contains—"],[1,"(1) the name and percentage of each active ingredient, and the total percentage of all inert ingredients, in the pesticide; and"],[1,"(2) if the pesticide contains arsenic in any form, a statement of the percentages of total and water soluble arsenic, calculated as elementary arsenic."],[0,"(o) Insect"],[0,"The term \"insect\" means any of the numerous small invertebrate animals generally having the body more or less obviously segmented, for the most part belonging to the class insecta, comprising six-legged, usually winged forms, as for example, beetles, bugs, bees, flies, and to other allied classes of arthropods whose members are wingless and usually have more than six legs, as for example, spiders, mites, ticks, centipedes, and wood lice."],[0,"(p) Label and labeling"],[0,"(1) Label"],[1,"The term \"label\" means the written, printed, or graphic matter on, or attached to, the pesticide or device or any of its containers or wrappers."],[0,"(2) Labeling"],[1,"The term \"labeling\" means all labels and all other written, printed, or graphic matter—"],[2,"(A) accompanying the pesticide or device at any time; or"],[2,"(B) to which reference is made on the label or in literature accompanying the pesticide or device, except to current official publications of the Environmental Protection Agency, the United States Departments of Agriculture and Interior, the Department of Health and Human Services, State experiment stations, State agricultural colleges, and other similar Federal or State institutions or agencies authorized by law to conduct research in the field of pesticides."],[0,"(q) Misbranded"],[1,"(1) A pesticide is misbranded if—"],[2,"(A) its labeling bears any statement, design, or graphic representation relative thereto or to its ingredients which is false or misleading in any particular;"],[2,"(B) it is contained in a package or other container or wrapping which does not conform to the standards established by the Administrator pursuant to section 136w(c)(3) of this title;"],[2,"(C) it is an imitation of, or is offered for sale under the name of, another pesticide;"],[2,"(D) its label does not bear the registration number assigned under section 136e of this title to each establishment in which it was produced;"],[2,"(E) any word, statement, or other information required by or under authority of this subchapter to appear on the label or labeling is not prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or graphic matter in the labeling) and in such terms as to render it likely to be read and understood by the ordinary individual under customary conditions of purchase and use;"],[2,"(F) the labeling accompanying it does not contain directions for use which are necessary for effecting the purpose for which the product is intended and if complied with, together with any requirements imposed under section 136a(d) of this title, are adequate to protect health and the environment;"],[2,"(G) the label does not contain a warning or caution statement which may be necessary and if complied with, together with any requirements imposed under section 136a(d) of this title, is adequate to protect health and the environment; or"],[2,"(H) in the case of a pesticide not registered in accordance with section 136a of this title and intended for export, the label does not contain, in words prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or graphic matter in the labeling) as to render it likely to be noted by the ordinary individual under customary conditions of purchase and use, the following: \"Not Registered for Use in the United States of America\"."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 23, 33, 36, 38, 41, 28, 27, 4, 7, 23, 41, 7, 23, 41, 50","1":"1-6, 8, 11-15, 18, 19, 22, 23, 25-28, 31, 32, 6, 21, 35, 19, 19, 2, 3, 6, 12, 17, 19, 23-25, 2, 6, 17, 1, 2, 6, 17, 24, 25, 34","2":"29, 51, 9, 2, 4, 10, 13, 18, 19, 20, 33, 39, 40, 2, 4, 10, 13, 18, 40","4":"13, 21, 10, 13, 21, 12, 13, 21"},"q":[{"src":"brief","b":0,"text":"any unreasonable risk to man or the environment, taking into account the economic, social, and environmental costs and benefits of the use of any pesticide.","cite":"7 U.S.C. §136(bb)"},{"src":"brief","b":0,"text":"necessary … to protect health and the environment,","cite":"7 U.S.C. §136(q)(1)(G)"},{"src":"brief","b":1,"text":"adequate to protect health and the environment.","cite":"7 U.S.C. 136(q)(1)(G)"},{"src":"brief","b":1,"text":"does not contain a warning or caution statement which may be necessary and * * * is adequate to protect health and the environment.","cite":"7 U.S.C. 136(q)(1)(A)"},{"src":"brief","b":2,"text":"bears any statement … which is false or misleading in any particular.","cite":"7 U.S.C. § 136(q)(1)(A)"},{"src":"brief","b":2,"text":"does not contain a warning or caution statement which may be necessary … to protect health and the environment.","cite":"7 U.S.C. § 136(q)(1)(G)"},{"src":"brief","b":4,"text":"necessary and … adequate to protect health and the environment.","cite":"7 U.S.C. §136(bb)"},{"src":"brief","b":4,"text":"tak[e] into account the economic, social, and environmental costs and benefits of the use of any pesticide.","cite":"7 U.S.C. §136(bb)"}]},{"t":"usc","label":"7 U.S.C. § 136a","url":"https://www.law.cornell.edu/uscode/text/7/136a","subs":["(a)","(c)","(c)(2)","(c)(5)","(f)(2)","(g)(1)","(c)(1)(C)","(c)(1)(D)","(c)(1)(F)","(c)(5)(B)","(c)(5)(D)","(c)(7)(A)","(g)(1)(A)(iii)(II)","(g)(1)(A)(iv)","(c)(3)(A)","(c)(5)(A)","(c)(6)","(f)(1)"],"stext":{"head":"§136a. Registration of pesticides","paras":[[0,"(a) Requirement of registration"],[0,"Except as provided by this subchapter, no person in any State may distribute or sell to any person any pesticide that is not registered under this subchapter. To the extent necessary to prevent unreasonable adverse effects on the environment, the Administrator may by regulation limit the distribution, sale, or use in any State of any pesticide that is not registered under this subchapter and that is not the subject of an experimental use permit under section 136c of this title or an emergency exemption under section 136p of this title."],[0,"(b) Exemptions"],[0,"A pesticide which is not registered with the Administrator may be transferred if—"],[1,"(1) the transfer is from one registered establishment to another registered establishment operated by the same producer solely for packaging at the second establishment or for use as a constituent part of another pesticide produced at the second establishment; or"],[1,"(2) the transfer is pursuant to and in accordance with the requirements of an experimental use permit."],[0,"(c) Procedure for registration"],[0,"(1) Statement required"],[1,"Each applicant for registration of a pesticide shall file with the Administrator a statement which includes—"],[2,"(A) the name and address of the applicant and of any other person whose name will appear on the labeling;"],[2,"(B) the name of the pesticide;"],[2,"(C) a complete copy of the labeling of the pesticide, a statement of all claims to be made for it, and any directions for its use;"],[2,"(D) the complete formula of the pesticide;"],[2,"(E) a request that the pesticide be classified for general use or for restricted use, or for both; and"],[2,"(F) except as otherwise provided in paragraph (2)(D), if requested by the Administrator, a full description of the tests made and the results thereof upon which the claims are based, or alternatively a citation to data that appear in the public literature or that previously had been submitted to the Administrator and that the Administrator may consider in accordance with the following provisions:"],[3,"(i) With respect to pesticides containing active ingredients that are initially registered under this subchapter after September 30, 1978, data submitted to support the application for the original registration of the pesticide, or an application for an amendment adding any new use to the registration and that pertains solely to such new use, shall not, without the written permission of the original data submitter, be considered by the Administrator to support an application by another person during a period of ten years following the date the Administrator first registers the pesticide, except that such permission shall not be required in the case of defensive data."],[3,"(ii) The period of exclusive data use provided under clause (i) shall be extended 1 additional year for each 3 minor uses registered after August 3, 1996, and within 7 years of the commencement of the exclusive use period, up to a total of 3 additional years for all minor uses registered by the Administrator if the Administrator, in consultation with the Secretary of Agriculture, determines that, based on information provided by an applicant for registration or a registrant, that—"],[4,"(I) there are insufficient efficacious alternative registered pesticides available for the use;"],[4,"(II) the alternatives to the minor use pesticide pose greater risks to the environment or human health;"],[4,"(III) the minor use pesticide plays or will play a significant part in managing pest resistance; or"],[4,"(IV) the minor use pesticide plays or will play a significant part in an integrated pest management program."],[0,"The registration of a pesticide for a minor use on a crop grouping established by the Administrator shall be considered for purposes of this clause 1 minor use for each representative crop for which data are provided in the crop grouping. Any additional exclusive use period under this clause shall be modified as appropriate or terminated if the registrant voluntarily cancels the product or deletes from the registration the minor uses which formed the basis for the extension of the additional exclusive use period or if the Administrator determines that the registrant is not actually marketing the product for such minor uses."],[3,"(iii) Except as otherwise provided in clause (i), with respect to data submitted after December 31, 1969, by an applicant or registrant to support an application for registration, experimental use permit, or amendment adding a new use to an existing registration, to support or maintain in effect an existing registration, or for reregistration, the Administrator may, without the permission of the original data submitter, consider any such item of data in support of an application by any other person (hereinafter in this subparagraph referred to as the \"applicant\") within the fifteen-year period following the date the data were originally submitted only if the applicant has made an offer to compensate the original data submitter and submitted such offer to the Administrator accompanied by evidence of delivery to the original data submitter of the offer. The terms and amount of compensation may be fixed by agreement between the original data submitter and the applicant, or, failing such agreement, binding arbitration under this subparagraph. If, at the end of ninety days after the date of delivery to the original data submitter of the offer to compensate, the original data submitter and the applicant have neither agreed on the amount and terms of compensation nor on a procedure for reaching an agreement on the amount and terms of compensation, either person may initiate binding arbitration proceedings by requesting the Federal Mediation and Conciliation Service to appoint an arbitrator from the roster of arbitrators maintained by such Service. The procedure and rules of the Service shall be applicable to the selection of such arbitrator and to such arbitration proceedings, and the findings and determination of the arbitrator shall be final and conclusive, and no official or court of the United States shall have power or jurisdiction to review any such findings and determination, except for fraud, misrepresentation, or other misconduct by one of the parties to the arbitration or the arbitrator where there is a verified complaint with supporting affidavits attesting to specific instances of such fraud, misrepresentation, or other misconduct. The parties to the arbitration shall share equally in the payment of the fee and expenses of the arbitrator. If the Administrator determines that an original data submitter has failed to participate in a procedure for reaching an agreement or in an arbitration proceeding as required by this subparagraph, or failed to comply with the terms of an agreement or arbitration decision concerning compensation under this subparagraph, the original data submitter shall forfeit the right to compensation for the use of the data in support of the application. Notwithstanding any other provision of this subchapter, if the Administrator determines that an applicant has failed to participate in a procedure for reaching an agreement or in an arbitration proceeding as required by this subparagraph, or failed to comply with the terms of an agreement or arbitration decision concerning compensation under this subparagraph, the Administrator shall deny the application or cancel the registration of the pesticide in support of which the data were used without further hearing. Before the Administrator takes action under either of the preceding two sentences, the Administrator shall furnish to the affected person, by certified mail, notice of intent to take action and allow fifteen days from the date of delivery of the notice for the affected person to respond. If a registration is denied or canceled under this subparagraph, the Administrator may make such order as the Administrator deems appropriate concerning the continued sale and use of existing stocks of such pesticide. Registration action by the Administrator shall not be delayed pending the fixing of compensation."],[3,"(iv) After expiration of any period of exclusive use and any period for which compensation is required for the use of an item of data under clauses (i), (ii), and (iii), the Administrator may consider such item of data in support of an application by any other applicant without the permission of the original data submitter and without an offer having been received to compensate the original data submitter for the use of such item of data."],[3,"(v) The period of exclusive use provided under clause (ii) shall not take effect until 1 year after August 3, 1996, except where an applicant or registrant is applying for the registration of a pesticide containing an active ingredient not previously registered."],[3,"(vi) With respect to data submitted after August 3, 1996, by an applicant or registrant to support an amendment adding a new use to an existing registration that does not retain any period of exclusive use, if such data relates solely to a minor use of a pesticide, such data shall not, without the written permission of the original data submitter, be considered by the Administrator to support an application for a minor use by another person during the period of 10 years following the date of submission of such data. The applicant or registrant at the time the new minor use is requested shall notify the Administrator that to the best of their knowledge the exclusive use period for the pesticide has expired and that the data pertaining solely to the minor use of a pesticide is eligible for the provisions of this paragraph. If the minor use registration which is supported by data submitted pursuant to this subsection is voluntarily canceled or if such data are subsequently used to support a nonminor use, the data shall no longer be subject to the exclusive use provisions of this clause but shall instead be considered by the Administrator in accordance with the provisions of clause (i), as appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136a?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 45, 8, 24, 7, 23, 33, 38, 39, 8, 9, 38","1":"20, 5, 20, 5, 6, 5, 5, 5, 19, 2, 6, 19, 1, 19, 34, 1, 6, 22, 13, 25-27, 7, 7","2":"8, 8, 11, 19, 38, 8, 8, 22, 2, i, 8, 10, 23, 2, 9, i, 6, 9, 10, 11, 17, 28, 30, 32","3":"18, 7","4":"12, 10, 20, 20, 21, 14"},"q":[{"src":"brief","b":0,"text":"a defense for the commission of any offense under this subchapter.","cite":"7 U.S.C. §136a(f)(2)"},{"src":"brief","b":0,"text":"prima facie evidence that [a] pesticide, its labeling and packaging comply with the registration provisions of the subchapter.","cite":"7 U.S.C. §136a(f)(2)"},{"src":"brief","b":1,"text":"full description of the tests made and the results thereof upon which the claims are based.","cite":"7 U.S.C. 136a(c)(1)(C)"},{"src":"brief","b":1,"text":"compl[ies] with the requirements of [FIFRA].","cite":"7 U.S.C. 136a(c)(5)(B)"},{"src":"brief","b":2,"text":"a complete copy of the labeling.","cite":"7 U.S.C. § 136a(c)(1)(C)"},{"src":"brief","b":2,"text":"its labeling and other material required to be submitted comply with the requirements of this subchapter.","cite":"7 U.S.C. § 136a(c)(5)(B)"},{"src":"brief","b":4,"text":"labeling and other material required to be submitted comply with the requirements of this subchapter.","cite":"7 U.S.C. §136a(c)(5)(B)"},{"src":"brief","b":4,"text":"a defense for the commission of any offense under this subchapter.","cite":"7 U.S.C. §136a(f)(2)"}]},{"t":"usc","label":"7 U.S.C. § 136a-1","url":"https://www.law.cornell.edu/uscode/text/7/136a-1","subs":["(b)(5)","(d)(3)","(g)","(m)"],"by":{"0":"49, 31, 27, 8","1":"7"}},{"t":"usc","label":"7 U.S.C. § 136d","url":"https://www.law.cornell.edu/uscode/text/7/136d","subs":["(a)(2)","(b)","(2)"],"stext":{"head":"§136d. Administrative review; suspension","paras":[[0,"(a) Existing stocks and information"],[0,"(1) Existing stocks"],[1,"The Administrator may permit the continued sale and use of existing stocks of a pesticide whose registration is suspended or canceled under this section, or section 136a or 136a–1 of this title, to such extent, under such conditions, and for such uses as the Administrator determines that such sale or use is not inconsistent with the purposes of this subchapter."],[0,"(2) Information"],[1,"If at any time after the registration of a pesticide the registrant has additional factual information regarding unreasonable adverse effects on the environment of the pesticide, the registrant shall submit such information to the Administrator."],[0,"(b) Cancellation and change in classification"],[0,"If it appears to the Administrator that a pesticide or its labeling or other material required to be submitted does not comply with the provisions of this subchapter or, when used in accordance with widespread and commonly recognized practice, generally causes unreasonable adverse effects on the environment, the Administrator may issue a notice of the Administrator's intent either—"],[1,"(1) to cancel its registration or to change its classification together with the reasons (including the factual basis) for the Administrator's action, or"],[1,"(2) to hold a hearing to determine whether or not its registration should be canceled or its classification changed."],[0,"Such notice shall be sent to the registrant and made public. In determining whether to issue any such notice, the Administrator shall include among those factors to be taken into account the impact of the action proposed in such notice on production and prices of agricultural commodities, retail food prices, and otherwise on the agricultural economy. At least 60 days prior to sending such notice to the registrant or making public such notice, whichever occurs first, the Administrator shall provide the Secretary of Agriculture with a copy of such notice and an analysis of such impact on the agricultural economy. If the Secretary comments in writing to the Administrator regarding the notice and analysis within 30 days after receiving them, the Administrator shall publish in the Federal Register (with the notice) the comments of the Secretary and the response of the Administrator with regard to the Secretary's comments. If the Secretary does not comment in writing to the Administrator regarding the notice and analysis within 30 days after receiving them, the Administrator may notify the registrant and make public the notice at any time after such 30-day period notwithstanding the foregoing 60-day time requirement. The time requirements imposed by the preceding 3 sentences may be waived or modified to the extent agreed upon by the Administrator and the Secretary. Notwithstanding any other provision of this subsection and section 136w(d) of this title, in the event that the Administrator determines that suspension of a pesticide registration is necessary to prevent an imminent hazard to human health, then upon such a finding the Administrator may waive the requirement of notice to and consultation with the Secretary of Agriculture pursuant to this subsection and of submission to the Scientific Advisory Panel pursuant to section 136w(d) of this title and proceed in accordance with subsection (c). When a public health use is affected, the Secretary of Health and Human Services should provide available benefits and use information, or an analysis thereof, in accordance with the procedures followed and subject to the same conditions as the Secretary of Agriculture in the case of agricultural pesticides. The proposed action shall become final and effective at the end of 30 days from receipt by the registrant, or publication, of a notice issued under paragraph (1), whichever occurs later, unless within that time either (i) the registrant makes the necessary corrections, if possible, or (ii) a request for a hearing is made by a person adversely affected by the notice. In the event a hearing is held pursuant to such a request or to the Administrator's determination under paragraph (2), a decision pertaining to registration or classification issued after completion of such hearing shall be final. In taking any final action under this subsection, the Administrator shall consider restricting a pesticide's use or uses as an alternative to cancellation and shall fully explain the reasons for these restrictions, and shall include among those factors to be taken into account the impact of such final action on production and prices of agricultural commodities, retail food prices, and otherwise on the agricultural economy, and the Administrator shall publish in the Federal Register an analysis of such impact."],[0,"(c) Suspension"],[0,"(1) Order"],[1,"If the Administrator determines that action is necessary to prevent an imminent hazard during the time required for cancellation or change in classification proceedings, the Administrator may, by order, suspend the registration of the pesticide immediately. Except as provided in paragraph (3), no order of suspension may be issued under this subsection unless the Administrator has issued, or at the same time issues, a notice of intention to cancel the registration or change the classification of the pesticide under subsection (b). Except as provided in paragraph (3), the Administrator shall notify the registrant prior to issuing any suspension order. Such notice shall include findings pertaining to the question of \"imminent hazard\". The registrant shall then have an opportunity, in accordance with the provisions of paragraph (2), for an expedited hearing before the Administrator on the question of whether an imminent hazard exists."],[0,"(2) Expedite hearing"],[1,"If no request for a hearing is submitted to the Administrator within five days of the registrant's receipt of the notification provided for by paragraph (1), the suspension order may be issued and shall take effect and shall not be reviewable by a court. If a hearing is requested, it shall commence within five days of the receipt of the request for such hearing unless the registrant and the Administrator agree that it shall commence at a later time. The hearing shall be held in accordance with the provisions of subchapter II of chapter 5 of title 5, except that the presiding officer need not be a certified administrative law judge. The presiding officer shall have ten days from the conclusion of the presentation of evidence to submit recommended findings and conclusions to the Administrator, who shall then have seven days to render a final order on the issue of suspension."],[0,"(3) Emergency order"],[1,"Whenever the Administrator determines that an emergency exists that does not permit the Administrator to hold a hearing before suspending, the Administrator may issue a suspension order in advance of notification to the registrant. The Administrator may issue an emergency order under this paragraph before issuing a notice of intention to cancel the registration or change the classification of the pesticide under subsection (b) and the Administrator shall proceed to issue the notice under subsection (b) within 90 days of issuing an emergency order. If the Administrator does not issue a notice under subsection (b) within 90 days of issuing an emergency order, the emergency order shall expire. In the case of an emergency order, paragraph (2) shall apply except that (A) the order of suspension shall be in effect pending the expeditious completion of the remedies provided by that paragraph and the issuance of a final order on suspension, and (B) no party other than the registrant and the Administrator shall participate except that any person adversely affected may file briefs within the time allotted by the Agency's rules. Any person so filing briefs shall be considered a party to such proceeding for the purposes of section 136n(b) of this title."],[0,"(4) Judicial review"],[1,"A final order on the question of suspension following a hearing shall be reviewable in accordance with section 136n of this title, notwithstanding the fact that any related cancellation proceedings have not been completed. Any order of suspension entered prior to a hearing before the Administrator shall be subject to immediate review in an action by the registrant or other interested person with the concurrence of the registrant in an appropriate district court, solely to determine whether the order of suspension was arbitrary, capricious or an abuse of discretion, or whether the order was issued in accordance with the procedures established by law. The effect of any order of the court will be only to stay the effectiveness of the suspension order, pending the Administrator's final decision with respect to cancellation or change in classification. This action may be maintained simultaneously with any administrative review proceedings under this section. The commencement of proceedings under this paragraph shall not operate as a stay of order, unless ordered by the court."],[0,"(d) Public hearings and scientific review"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136d?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 26, 38, 9, 26","1":"7, 26, 7, 19, 21","2":"2, 2","3":"19, 18","4":"11, 13"},"q":[{"src":"brief","b":0,"text":"additional factual information regarding unreasonable adverse effects.","cite":"7 U.S.C. §136d(a)(2)"},{"src":"brief","b":0,"text":"regarding unreasonable adverse effects on the environment.","cite":"7 U.S.C. §136d(a)(2)"},{"src":"brief","b":1,"text":"additional factual information regarding unreasonable adverse effects.","cite":"7 U.S.C. 136d(a)(2)"},{"src":"brief","b":1,"text":"generally causes unreasonable adverse effects on the environment","cite":"7 U.S.C. 136d(b)"},{"src":"brief","b":3,"text":"additional factual information regarding unreasonable adverse effects on the environment,","cite":"7 U.S.C. § 136d(2)"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"additional factual information regarding unreasonable adverse effects","cite":"7 U. S. C. § 136d(a)(2)"}]},{"t":"usc","label":"7 U.S.C. § 136h","url":"https://www.law.cornell.edu/uscode/text/7/136h","subs":["(a)"],"by":{"0":"27"}},{"t":"usc","label":"7 U.S.C. § 136j","url":"https://www.law.cornell.edu/uscode/text/7/136j","subs":["(a)(1)","(a)(2)","(a)(1)(A)","(a)(1)(B)","(a)(1)(C)","(a)(1)(E)","(a)(2)(F)","(a)(2)(G)"],"stext":{"head":"§136j. Unlawful acts","paras":[[0,"(a) In general"],[0,"(1) Except as provided by subsection (b), it shall be unlawful for any person in any State to distribute or sell to any person—"],[1,"(A) any pesticide that is not registered under section 136a of this title or whose registration has been canceled or suspended, except to the extent that distribution or sale otherwise has been authorized by the Administrator under this subchapter;"],[1,"(B) any registered pesticide if any claims made for it as a part of its distribution or sale substantially differ from any claims made for it as a part of the statement required in connection with its registration under section 136a of this title;"],[1,"(C) any registered pesticide the composition of which differs at the time of its distribution or sale from its composition as described in the statement required in connection with its registration under section 136a of this title;"],[1,"(D) any pesticide which has not been colored or discolored pursuant to the provisions of section 136w(c)(5) of this title;"],[1,"(E) any pesticide which is adulterated or misbranded; or"],[1,"(F) any device which is misbranded."],[0,"(2) It shall be unlawful for any person—"],[1,"(A) to detach, alter, deface, or destroy, in whole or in part, any labeling required under this subchapter;"],[1,"(B) to refuse to—"],[2,"(i) prepare, maintain, or submit any records required by or under section 136c, 136e, 136f, 136i, or 136q of this title;"],[2,"(ii) submit any reports required by or under section 136c, 136d, 136e, 136f, 136i, or 136q of this title; or"],[2,"(iii) allow any entry, inspection, copying of records, or sampling authorized by this subchapter;"],[1,"(C) to give a guaranty or undertaking provided for in subsection (b) which is false in any particular, except that a person who receives and relies upon a guaranty authorized under subsection (b) may give a guaranty to the same effect, which guaranty shall contain, in addition to the person's own name and address, the name and address of the person residing in the United States from whom the person received the guaranty or undertaking;"],[1,"(D) to use for the person's own advantage or to reveal, other than to the Administrator, or officials or employees of the Environmental Protection Agency or other Federal executive agencies, or to the courts, or to physicians, pharmacists, and other qualified persons, needing such information for the performance of their duties, in accordance with such directions as the Administrator may prescribe, any information acquired by authority of this subchapter which is confidential under this subchapter;"],[1,"(E) who is a registrant, wholesaler, dealer, retailer, or other distributor to advertise a product registered under this subchapter for restricted use without giving the classification of the product assigned to it under section 136a of this title;"],[1,"(F) to distribute or sell, or to make available for use, or to use, any registered pesticide classified for restricted use for some or all purposes other than in accordance with section 136a(d) of this title and any regulations thereunder, except that it shall not be unlawful to sell, under regulations issued by the Administrator, a restricted use pesticide to a person who is not a certified applicator for application by a certified applicator;"],[1,"(G) to use any registered pesticide in a manner inconsistent with its labeling;"],[1,"(H) to use any pesticide which is under an experimental use permit contrary to the provisions of such permit;"],[1,"(I) to violate any order issued under section 136k of this title;"],[1,"(J) to violate any suspension order issued under section 136a(c)(2)(B), 136a–1, or 136d of this title;"],[1,"(K) to violate any cancellation order issued under this subchapter or to fail to submit a notice in accordance with section 136d(g) of this title;"],[1,"(L) who is a producer to violate any of the provisions of section 136e of this title;"],[1,"(M) to knowingly falsify all or part of any application for registration, application for experimental use permit, any information submitted to the Administrator pursuant to section 136e of this title, any records required to be maintained pursuant to this subchapter, any report filed under this subchapter, or any information marked as confidential and submitted to the Administrator under any provision of this subchapter;"],[1,"(N) who is a registrant, wholesaler, dealer, retailer, or other distributor to fail to file reports required by this subchapter;"],[1,"(O) to add any substance to, or take any substance from, any pesticide in a manner that may defeat the purpose of this subchapter;"],[1,"(P) to use any pesticide in tests on human beings unless such human beings (i) are fully informed of the nature and purposes of the test and of any physical and mental health consequences which are reasonably foreseeable therefrom, and (ii) freely volunteer to participate in the test;"],[1,"(Q) to falsify all or part of any information relating to the testing of any pesticide (or any ingredient, metabolite, or degradation product thereof), including the nature of any protocol, procedure, substance, organism, or equipment used, observation made, or conclusion or opinion formed, submitted to the Administrator, or that the person knows will be furnished to the Administrator or will become a part of any records required to be maintained by this subchapter;"],[1,"(R) to submit to the Administrator data known to be false in support of a registration; or"],[1,"(S) to violate any regulation issued under section 136a(a) or 136q of this title."],[0,"(b) Exemptions"],[0,"The penalties provided for a violation of paragraph (1) of subsection (a) shall not apply to—"],[1,"(1) any person who establishes a guaranty signed by, and containing the name and address of, the registrant or person residing in the United States from whom the person purchased or received in good faith the pesticide in the same unbroken package, to the effect that the pesticide was lawfully registered at the time of sale and delivery to the person, and that it complies with the other requirements of this subchapter, and in such case the guarantor shall be subject to the penalties which would otherwise attach to the person holding the guaranty under the provisions of this subchapter;"],[1,"(2) any carrier while lawfully shipping, transporting, or delivering for shipment any pesticide or device, if such carrier upon request of any officer or employee duly designated by the Administrator shall permit such officer or employee to copy all of its records concerning such pesticide or device;"],[1,"(3) any public official while engaged in the performance of the official duties of the public official;"],[1,"(4) any person using or possessing any pesticide as provided by an experimental use permit in effect with respect to such pesticide and such use or possession; or"],[1,"(5) any person who ships a substance or mixture of substances being put through tests in which the purpose is only to determine its value for pesticide purposes or to determine its toxicity or other properties and from which the user does not expect to receive any benefit in pest control from its use."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136j?type=usc&year=mostrecent&link-type=html"},"by":{"0":"9, 21, 25, 30, 45, 27, 28","1":"5, 5, 20, 5, 20, 6, 17, 20, 5, 20","2":"33, i, 2, 7, 9, 1, 11, 18, 29, 38, 39, 2, 30, i, 2, 8, 9, 19, 21, 29, 44","4":"14"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"the statement required in connection with its registration.","cite":"7 U. S. C. § 136j(a)(1)(B)"}]},{"t":"usc","label":"7 U.S.C. § 136k","url":"https://www.law.cornell.edu/uscode/text/7/136k","subs":["(b)","(a)","(c)"],"by":{"0":"27","1":"21, 5, 5","2":"31"}},{"t":"usc","label":"7 U.S.C. § 136v","url":"https://www.law.cornell.edu/uscode/text/7/136v","subs":["(a)","(b)","(c)(1)","(c)","(b)(2)"],"stext":{"head":"§136v. Authority of States","paras":[[0,"(a) In general"],[0,"A State may regulate the sale or use of any federally registered pesticide or device in the State, but only if and to the extent the regulation does not permit any sale or use prohibited by this subchapter."],[0,"(b) Uniformity"],[0,"Such State shall not impose or continue in effect any requirements for labeling or packaging in addition to or different from those required under this subchapter."],[0,"(c) Additional uses"],[0,"(1) A State may provide registration for additional uses of federally registered pesticides formulated for distribution and use within that State to meet special local needs in accord with the purposes of this subchapter and if registration for such use has not previously been denied, disapproved, or canceled by the Administrator. Such registration shall be deemed registration under section 136a of this title for all purposes of this subchapter, but shall authorize distribution and use only within such State."],[0,"(2) A registration issued by a State under this subsection shall not be effective for more than ninety days if disapproved by the Administrator within that period. Prior to disapproval, the Administrator shall, except as provided in paragraph (3) of this subsection, advise the State of the Administrator's intention to disapprove and the reasons therefor, and provide the State time to respond. The Administrator shall not prohibit or disapprove a registration issued by a State under this subsection (A) on the basis of lack of essentiality of a pesticide or (B) except as provided in paragraph (3) of this subsection, if its composition and use patterns are similar to those of a federally registered pesticide."],[0,"(3) In no instance may a State issue a registration for a food or feed use unless there exists a tolerance or exemption under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] that permits the residues of the pesticides on the food or feed. If the Administrator determines that a registration issued by a State is inconsistent with the Federal Food, Drug, and Cosmetic Act, or the use of, a pesticide under a registration issued by a State constitutes an imminent hazard, the Administrator may immediately disapprove the registration."],[0,"(4) If the Administrator finds, in accordance with standards set forth in regulations issued under section 136w of this title, that a State is not capable of exercising adequate controls to assure that State registration under this section will be in accord with the purposes of this subchapter or has failed to exercise adequate controls, the Administrator may suspend the authority of the State to register pesticides until such time as the Administrator is satisfied that the State can and will exercise adequate controls. Prior to any such suspension, the Administrator shall advise the State of the Administrator's intention to suspend and the reasons therefor and provide the State time to respond."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136v?type=usc&year=mostrecent&link-type=html"},"by":{"0":"10, 1, 10, 20, 21, 23, 26, 27, 28, 34, 35, 10","1":"7, 8, 28, 35, 3, 4, 8, 11, 12, 14-17, 20, 28, 33, 35, 8","2":"i, 3, 12, 20, 21, 32, 36, 50, 13","3":"5, 10, 11, 4, 5, 10, 11","4":"1, 3"},"q":[{"src":"brief","b":0,"text":"requirements for labeling or packaging in addition to or different from those required under this subchapter.","cite":"7 U.S.C. §136v(b)"},{"src":"brief","b":0,"text":"requirements for labeling … under this subchapter,","cite":"7 U.S.C. §136v(b)"},{"src":"brief","b":1,"text":"requirements for labeling or packaging in addition to or different from those required under this subchapter,","cite":"7 U.S.C. 136v(b)"},{"src":"brief","b":1,"text":"in addition to or different from those required under","cite":"7 U.S.C. 136v(b)"},{"src":"brief","b":2,"text":"in addition to or different from those required under this subchapter.","cite":"7 U.S.C. § 136v(b)"},{"src":"brief","b":2,"text":"in addition to or different from those required under","cite":"7 U.S.C. § 136v(b)"}]},{"t":"usc","label":"7 U.S.C. § 136w","url":"https://www.law.cornell.edu/uscode/text/7/136w","subs":["(d)"],"by":{"0":"24","1":"1"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"prescribe regulations to carry out the provisions of [FIFRA].","cite":"7 U. S. C. § 136w(a)(1)"}]},{"t":"usc","label":"21 U.S.C. § 360k","url":"https://www.law.cornell.edu/uscode/text/21/360k","subs":["(a)","(a)(1)"],"stext":{"head":"§360k. State and local requirements respecting devices","paras":[[0,"(a) General rule"],[0,"Except as provided in subsection (b), no State or political subdivision of a State may establish or continue in effect with respect to a device intended for human use any requirement—"],[1,"(1) which is different from, or in addition to, any requirement applicable under this chapter to the device, and"],[1,"(2) which relates to the safety or effectiveness of the device or to any other matter included in a requirement applicable to the device under this chapter."],[0,"(b) Exempt requirements"],[0,"Upon application of a State or a political subdivision thereof, the Secretary may, by regulation promulgated after notice and opportunity for an oral hearing, exempt from subsection (a), under such conditions as may be prescribed in such regulation, a requirement of such State or political subdivision applicable to a device intended for human use if—"],[1,"(1) the requirement is more stringent than a requirement under this chapter which would be applicable to the device if an exemption were not in effect under this subsection; or"],[1,"(2) the requirement—"],[2,"(A) is required by compelling local conditions, and"],[2,"(B) compliance with the requirement would not cause the device to be in violation of any applicable requirement under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360k?type=usc&year=mostrecent&link-type=html"},"by":{"0":"29","1":"12, 21","2":"50"},"q":[{"src":"brief","b":0,"text":"is different from, or in addition to, any requirement applicable under this chapter,","cite":"21 U.S.C. §360k(a)"},{"src":"brief","b":1,"text":"different from, or in addition to, any requirement applicable under this chapter to the device.","cite":"21 U.S.C. 360k(a)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"no State . . . may establish or continue in effect with respect to a device intended for human use any requirement—(1) which is different from, or in addition to, any requirement applicable under this chapter to the device, and (2) which relates to the safety or effectiveness of the device or to any other matter included in a requirement applicable to the device under this chapter.","cite":"21 U. S. C. § 360k(a)"}]},{"t":"law","label":"Pub. L. No. 80-104","by":{"0":"4, 5"}},{"t":"law","label":"Pub. L. No. 88-305","url":"https://www.govinfo.gov/link/statute/78/190","by":{"0":"5","1":"26"}},{"t":"law","label":"Pub. L. No. 92-516","url":"https://www.govinfo.gov/link/statute/86/973","by":{"0":"4, 5, 6","1":"27","3":"11"}},{"t":"reg","label":"40 C.F.R. § 152.40","url":"https://www.ecfr.gov/current/title-40/section-152.40","by":{"0":"8, 30"}},{"t":"reg","label":"40 C.F.R. § 152.44","url":"https://www.ecfr.gov/current/title-40/section-152.44","subs":["(a)"],"by":{"0":"9, 30, 45, 25, 45","2":"39","4":"18"},"q":[{"src":"brief","b":0,"text":"any modification in the composition, labeling, or packaging of a registered product.","cite":"40 C.F.R. §152.44(a)"}]},{"t":"reg","label":"40 C.F.R. § 152.46","url":"https://www.ecfr.gov/current/title-40/section-152.46","subs":["(a)(1)","(a)"],"by":{"0":"9, 30, 45","2":"39, 40","3":"18","4":"18"},"q":[{"src":"brief","b":4,"text":"proceed through notification without the need for EPA approval.","cite":"40 C.F.R. §152.46(a)"}]},{"t":"reg","label":"40 C.F.R. § 152.50","url":"https://www.ecfr.gov/current/title-40/section-152.50","subs":["(e)","(f)(3)"],"by":{"0":"45","3":"18, 18"}},{"t":"reg","label":"40 C.F.R. § 152.80","url":"https://www.ecfr.gov/current/title-40/section-152.80","by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 152.85","url":"https://www.ecfr.gov/current/title-40/section-152.85","subs":["(e)"],"by":{"0":"8, 42"},"q":[{"src":"brief","b":0,"text":"review all data that are necessary to make the required risk/benefit finding under FIFRA.","cite":"40 C.F.R. §152.85(e)"},{"src":"brief","b":0,"text":"not approve an application unless there are available to EPA for its review all data that are necessary to make the required risk/benefit finding under FIFRA section 3(c)(5) or section 3(c)(7).","cite":"40 C.F.R. §152.85(e)"}]},{"t":"reg","label":"40 C.F.R. § 152.105","url":"https://www.ecfr.gov/current/title-40/section-152.105","by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 152.112","url":"https://www.ecfr.gov/current/title-40/section-152.112","subs":["(e)","(f)"],"by":{"0":"7, 30, 23, 7, 30, 8, 23"},"q":[{"src":"brief","b":0,"text":"its labeling and packaging comply with the applicable requirements","cite":"40 C.F.R. §152.112(e)"}]},{"t":"reg","label":"40 C.F.R. § 152.170","url":"https://www.ecfr.gov/current/title-40/section-152.170","subs":["(a)(4)","(a)","(a)(2)","(e)(2)"],"by":{"0":"42","4":"13, 13, 13"}},{"t":"reg","label":"40 C.F.R. § 152.171","url":"https://www.ecfr.gov/current/title-40/section-152.171","subs":["(b)"],"by":{"0":"42"}},{"t":"reg","label":"40 C.F.R. § 154.1","url":"https://www.ecfr.gov/current/title-40/section-154.1","subs":["(a)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 154.25","url":"https://www.ecfr.gov/current/title-40/section-154.25","subs":["(d)"],"by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 154.7","url":"https://www.ecfr.gov/current/title-40/section-154.7","subs":["(a)(5)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 155.40","url":"https://www.ecfr.gov/current/title-40/section-155.40","subs":["(a)(2)"],"by":{"0":"9"}},{"t":"reg","label":"40 C.F.R. § 155.53","url":"https://www.ecfr.gov/current/title-40/section-155.53","subs":["(a)"],"by":{"0":"42"}},{"t":"reg","label":"40 C.F.R. § 155.58","url":"https://www.ecfr.gov/current/title-40/section-155.58","subs":["(b)(4)"],"by":{"0":"9, 8, 38, 50"}},{"t":"reg","label":"40 C.F.R. § 156.10","url":"https://www.ecfr.gov/current/title-40/section-156.10","subs":["(a)(1)","(a)(5)(vii)","(h)(2)"],"by":{"0":"8, 24","2":"10","4":"19"},"q":[{"src":"brief","b":2,"text":"used in such a way as to give a false or misleading impression to the purchaser.","cite":"40 C.F.R. § 156.10(a)(5)(vii)"}]},{"t":"reg","label":"40 C.F.R. § 156.60","url":"https://www.ecfr.gov/current/title-40/section-156.60","by":{"0":"8, 24"}},{"t":"reg","label":"40 C.F.R. § 156.70","url":"https://www.ecfr.gov/current/title-40/section-156.70","subs":["(c)","(a)"],"by":{"0":"9, 25, 45","4":"19, 18"},"q":[{"src":"brief","b":4,"text":"[h]uman hazard and precautionary statements as required must appear together on the label or labeling under the general heading ‘Precautionary Statements.","cite":"40 C.F.R. §156.70(a)"}]},{"t":"reg","label":"40 C.F.R. § 158.1","url":"https://www.ecfr.gov/current/title-40/section-158.1","subs":["(a)"],"by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"to make regulatory judgments under FIFRA … about the risks and benefits of pesticide products.","cite":"40 C.F.R. §158.1(a)"}]},{"t":"reg","label":"40 C.F.R. § 158.45","url":"https://www.ecfr.gov/current/title-40/section-158.45","subs":["(a)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 158.500","url":"https://www.ecfr.gov/current/title-40/section-158.500","by":{"0":"8, 24"}},{"t":"reg","label":"40 C.F.R. § 159.152","url":"https://www.ecfr.gov/current/title-40/section-159.152","by":{"0":"9","3":"19"}},{"t":"reg","label":"40 C.F.R. § 159.158","url":"https://www.ecfr.gov/current/title-40/section-159.158","subs":["(a)"],"by":{"0":"38"}},{"t":"reg","label":"40 C.F.R. § 166.3","url":"https://www.ecfr.gov/current/title-40/section-166.3","by":{"0":"23, 30"}},{"t":"reg","label":"49 Fed. Reg. 37,960","url":"https://www.govinfo.gov/link/fr/49/37960","by":{"0":"40"}},{"t":"reg","label":"73 Fed. Reg. 73,586","url":"https://www.govinfo.gov/link/fr/73/73586","by":{"0":"12"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"by":{"1":"17","4":"12"},"q":[{"src":"argument","who":"Mr. Clement","text":"And I think that's important, of course, because that would be the federal government essentially making sure that its registrants are continuing with their ongoing obligations, and that would sort of be more consistent with the thrust of Buckman, where is -- you know, if you have a situation where your concern is that somehow the registrant hasn't done something they're supposed to do vis- -vis the agency, you give the agency the ability to take care of that."}]},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"with any procedural requirements imposed by Congress.","cite":"441 U.S. 281, 303"}]},{"t":"case","label":"Hardeman v. Monsanto Co.","cite":"997 F.3d 941","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/941/","by":{"1":"14"}},{"t":"case","label":"Jones v. Rath Packing Co.","cite":"430 U.S. 519","y":1977,"id":"1976/75-1053","sc":1,"by":{"1":"18"}},{"t":"case","label":"Lipschultz v. Charter Adv. Servs. (MN), LLC","cite":"589 U.S. 1038","y":2019,"url":"https://supreme.justia.com/cases/federal/us/589/1038/","sc":1,"by":{"1":"20"}},{"t":"case","label":"National Meat Ass’n v. Harris","cite":"565 U.S. 452","y":2012,"id":"2011/10-224","sc":1,"by":{"1":"15","4":"9"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"by reason of the authority of","cite":"583 U.S. 109, 124"}]},{"t":"case","label":"Natural Res. Def. Council v. EPA","cite":"31 F.4th 1203","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/31/1203/","by":{"1":"7"}},{"t":"case","label":"Newman v. Ford Motor Co.","cite":"975 S.W.2d 147","y":1998,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/975/147/","by":{"1":"24, 25"},"q":[{"src":"brief","b":1,"text":"the utility of a design outweighs its risks,","cite":"975 S.W.2d 147, 154"},{"src":"brief","b":1,"text":"any other theory of unreasonable dangerousness supported by the evidence.","cite":"975 S.W.2d at 154"}]},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Trust","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"not invoke any presumption against preemption but instead ‘focus[es] on the plain wording of the clause.’","cite":"579 U.S. 115, 125"}]},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"by":{"1":"29"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"by":{"1":"20"}},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"even if it varies from a term’s ordinary meaning.","cite":"593 U.S. 374, 387"}]},{"t":"case","label":"Wisconsin Public Intervenor v. Mortier","cite":"501 U.S. 597","y":1991,"id":"1990/89-1905","sc":1,"by":{"1":"5","2":"7","3":"2, 9, 10"},"q":[{"src":"brief","b":1,"text":"significantly strengthened FIFRA’s registration and labeling standards.","cite":"501 U.S. 597, 601"},{"src":"brief","b":2,"text":"an affirmative permit scheme for the actual use of pesticides.","cite":"501 U.S. 597, 613"}]},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","by":{"1":"21"}},{"t":"usc","label":"7 U.S.C. § 136l","url":"https://www.law.cornell.edu/uscode/text/7/136l","subs":["(b)","(a)(1)"],"by":{"1":"5, 21, 20","2":"31, 31"}},{"t":"usc","label":"7 U.S.C. § 136n","url":"https://www.law.cornell.edu/uscode/text/7/136n","subs":["(b)"],"by":{"1":"7","2":"2"}},{"t":"usc","label":"21 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/21/601","by":{"1":"15"}},{"t":"usc","label":"21 U.S.C. § 678","url":"https://www.law.cornell.edu/uscode/text/21/678","by":{"1":"15, 18"}},{"t":"law","label":"Pub. L. No. 94-295","url":"https://www.govinfo.gov/link/statute/90/539","by":{"1":"12, 21"}},{"t":"usc","label":"21 U.S.C. § 360e","url":"https://www.law.cornell.edu/uscode/text/21/360e","subs":["(d)(5)(A)(i)"],"by":{"1":"22"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Industries, Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"by":{"2":"29"}},{"t":"case","label":"English v. General Electric Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"by":{"2":"34"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"2":"25"}},{"t":"case","label":"Haberly v. Reardon Co.","cite":"319 S.W.2d 859","y":1958,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/319/859/","by":{"2":"12, 33"}},{"t":"case","label":"La Plant v. E.I. DuPont De Nemours & Co.","cite":"346 S.W.2d 231","y":1961,"court":"Mo. Ct. App.","url":"https://www.courtlistener.com/c/S.W.2d/346/231/","by":{"2":"12, 33"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"2":"5, 10, 11, 21, 22, 24, 25, 26","4":"1"},"q":[{"src":"argument","who":"Mr. Keller","text":"I think, in the new Loper Bright regime, you would say point to text delegating that power to the agency directly. Well, they don't have that notice and comment rule."},{"src":"argument","who":"Mr. Keller","text":"Second, in Riegel, you found as a matter of the statute, not as a matter of regulation, we didn't have to ask a Loper Bright question, as a matter of the statute, that once the FDA approved the medical device, you couldn't depart from the label."},{"src":"argument","who":"Mr. Keller","text":"Again, maybe in the Chevron regime, we might have looked past that. But we're in the Loper Bright regime. I think you need affirmative text --"}]},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"is too extravagant to be maintained.","cite":"1 Cranch 137, 179"}]},{"t":"case","label":"Meeker v. Lehigh Valley R. Co.","cite":"236 U.S. 412","y":1915,"id":"scdb/1914-227","sc":1,"by":{"2":"30"},"q":[{"src":"brief","b":2,"text":"takes no question of fact from either court or jury.","cite":"236 U.S. 412, 430"}]},{"t":"case","label":"National Cable & Telecommunications Association v. Brand X Internet Services","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"by":{"2":"47"}},{"t":"case","label":"Nesselrode v. Executive Beechcraft, Inc.","cite":"707 S.W.2d 371","y":1986,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/707/371/","by":{"2":"12, 13, 33"},"q":[{"src":"brief","b":2,"text":"warning that has been given [that] is informationally deficient.","cite":"707 S.W.2d 371, 382"},{"src":"brief","b":2,"text":"give[] th[e] concept [of unreasonable danger] content by applying their collective intelligence and experience to the broad evidentiary spectrum of facts and circumstances presented by the parties.","cite":"707 S.W.2d at 378"}]},{"t":"case","label":"(vii) Racer v. Utterman","cite":"629 S.W.2d 387","y":1981,"court":"Mo. Ct. App.","url":"https://www.courtlistener.com/c/S.W.2d/629/387/","by":{"2":"3, 12, 13, 44"}},{"t":"case","label":"SEC v. Jarkesy","cite":"603 U.S. 109","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/109/","sc":1,"by":{"2":"31"}},{"t":"case","label":"Theatre Enterprises, Inc. v. Paramount Film Distributing Corp.","cite":"346 U.S. 537","y":1954,"id":"1940-1955/346us537","sc":1,"by":{"2":"30"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"by":{"2":"45"}},{"t":"case","label":"United States v. Carolene Products Co.","cite":"304 U.S. 144","y":1938,"id":"1900-1940/304us144","sc":1,"by":{"2":"27"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"by":{"2":"10, 26"},"q":[{"src":"argument","who":"Mr. Keller","text":"It went through an entirely formal process that in the Chevron regime would have unquestionably satisfied Mead, saying Roundup is perfectly safe, there's nothing wrong with glyphosate, if you put any type of warning on glyphosate, we, the EPA, determine that that would be misbranded."}]},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","by":{"2":"49"}},{"t":"usc","label":"28 U.S.C. § 453","url":"https://www.law.cornell.edu/uscode/text/28/453","by":{"2":"27"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"31"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"2":"4"}},{"t":"reg","label":"21 C.F.R. § 314.70","url":"https://www.ecfr.gov/current/title-21/section-314.70","subs":["(c)(1)","(c)(6)","(c)(7)"],"by":{"2":"42, 36, 42"}},{"t":"reg","label":"EPA, Pesticides; Guidance for Pesticide Registrants on Mandatory and Advisory Labeling Statements, 65 Fed. Reg. 31,313","url":"https://www.govinfo.gov/link/fr/65/31313","by":{"2":"41"}},{"t":"reg","label":"Executive Order No. 14387, Promoting the National Defense by Ensuring an Adequate Supply of Elemental Phosphorus and Glyphosate-Based Herbic, 91 Fed. Reg. 8703","url":"https://www.govinfo.gov/link/fr/91/8703","by":{"2":"28"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"by":{"3":"2, 11"}},{"t":"case","label":"Learning Resources, Inc. v. Trump, 607 U.S. ---","cite":"146 S. Ct. 628","y":2026,"id":"2025/24-1287","sc":1,"by":{"3":"2"}},{"t":"reg","label":"40 C.F.R. § 152.42","url":"https://www.ecfr.gov/current/title-40/section-152.42","by":{"3":"18"}},{"t":"reg","label":"40 C.F.R. § 159.155","url":"https://www.ecfr.gov/current/title-40/section-159.155","subs":["(b)"],"by":{"3":"19"}},{"t":"reg","label":"40 C.F.R. § 159.184","url":"https://www.ecfr.gov/current/title-40/section-159.184","subs":["(a)"],"by":{"3":"19"}},{"t":"case","label":"Geier v. Am. Honda Motor","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"by":{"4":"9"},"q":[{"src":"argument","who":"Mr. Keller","text":"You have cases like Geier, where you say you can still go on to implied preemption. But, here, it requires parallelism. It can't be in addition to or different from, so they have to be the same."}]},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"4":"4"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"by":{"4":"10"},"q":[{"src":"brief","b":4,"text":"a federal agency may pre-empt state law only when and if it is acting within the scope of its congressionally delegated authority.","cite":"535 U.S. 1, 18-19"}]},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"by":{"4":"4"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(a)","(j)(2)"],"by":{"4":"22, 22"}}]};